#include "sovereign/health.hpp"
namespace sovereign {
void HealthTracker::active_result(const Target& target,const HealthPolicy& policy,bool success,std::chrono::steady_clock::time_point now){std::lock_guard lock(mutex_);auto& history=history_[target.identity];if(success){history.successes++;history.failures=0;if(history.successes>=policy.healthy_threshold){eligibility_.state(target.identity).active_healthy=true;history.successes=policy.healthy_threshold;if(eligibility_.state(target.identity).ejected_until<=now)history.passive.clear();}}else{history.failures++;history.successes=0;if(history.failures>=policy.unhealthy_threshold){eligibility_.state(target.identity).active_healthy=false;history.failures=policy.unhealthy_threshold;}}}
void HealthTracker::passive_failure(const Target& target,const HealthPolicy& policy,std::chrono::steady_clock::time_point now){std::lock_guard lock(mutex_);auto& history=history_[target.identity];auto cutoff=now-std::chrono::milliseconds(policy.passive_window_ms);while(!history.passive.empty()&&history.passive.front()<cutoff)history.passive.pop_front();history.passive.push_back(now);if(static_cast<int>(history.passive.size())>=policy.passive_failures)eligibility_.state(target.identity).ejected_until=now+std::chrono::milliseconds(policy.ejection_ms);}
void HealthTracker::begin_drain(const Target& target,std::chrono::milliseconds timeout,std::chrono::steady_clock::time_point now){eligibility_.state(target.identity).drain_deadline=now+timeout;}
}